<?php
if (!defined('ABSPATH')) exit;
final class KCB_Mapping_Admin {
 const OPT='kcb_mapping';
 static function init(){add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_post_kcb_save_mapping',[__CLASS__,'save']);add_action('admin_post_kcb_preview_mapping',[__CLASS__,'preview']);}
 static function settings(){return wp_parse_args(get_option(self::OPT,[]),['fields'=>['customer_name'=>'name','mobile'=>'phone','email'=>'email','message'=>'message','consent'=>'consent','external_id'=>'external_id'],'array_path'=>'','yes'=>['yes','true','1'],'confirmed'=>false]);}
 static function menu(){add_submenu_page('kcb','Lead Field Mapping','Field Mapping','manage_options','kcb-mapping',[__CLASS__,'screen']);}
 static function clean_settings($in){$map=KCB_Field_Mapper::mapping($in['fields']??[]);if(is_wp_error($map))return $map;$array=trim((string)($in['array_path']??''));if($array!==''&&$array!=='$'&&!preg_match('/^[A-Za-z0-9_-]+(?:\.[A-Za-z0-9_-]+|\[[0-9]{1,5}\])*$/D',$array))return new WP_Error('path','Invalid array path.');$yes=array_values(array_unique(array_filter(array_map('trim',explode(',',(string)($in['yes']??''))), 'strlen')));if(!$yes)return new WP_Error('consent','Specify affirmative consent values.');return ['fields'=>$map,'array_path'=>$array,'yes'=>$yes,'confirmed'=>!empty($in['confirmed'])];}
 static function save(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('kcb_save_mapping');$clean=self::clean_settings(wp_unslash($_POST['mapping']??[]));if(is_wp_error($clean))wp_die(esc_html($clean->get_error_message()));update_option(self::OPT,$clean,false);wp_safe_redirect(admin_url('admin.php?page=kcb-mapping&saved=1'));exit;}
 static function preview(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('kcb_preview_mapping');$clean=self::clean_settings(wp_unslash($_POST['mapping']??[]));$sample=wp_unslash($_POST['sample_json']??'');$result=[];if(is_wp_error($clean))$result=['error'=>$clean->get_error_message()];else{$parsed=KCB_Field_Mapper::parse($sample);if(is_wp_error($parsed))$result=['error'=>$parsed->get_error_message()];else{$items=KCB_Field_Mapper::extract($parsed,$clean['array_path']);if(is_wp_error($items))$result=['error'=>$items->get_error_message()];else{$result=['suggestions'=>KCB_Field_Mapper::suggest($items[0]),'items'=>[]];foreach($items as $i=>$item){$mapped=KCB_Field_Mapper::normalize($item,$clean['fields'],$clean['yes']);$mapped['payload']['external_id']=$mapped['payload']['external_id']?:'[generated on submission]';$result['items'][]=['index'=>$i+1,'crm_payload'=>$mapped['payload'],'validation_errors'=>$mapped['errors']];}foreach($result['suggestions'] as $field=>$paths){if(count($paths)>1)$result['ambiguities'][$field]=$paths;}}}}
 // Do not persist or log sample JSON or preview. Output only in this response.
 self::screen($clean,$result);exit;}
 static function screen($draft=null,$preview=null){if(!current_user_can('manage_options'))return;$c=is_array($draft)?$draft:self::settings();echo '<div class="wrap"><h1>CRM Field Mapping</h1><p>Map source JSON fields to the fixed CRM lead format. This does not change the CRM API schema. Unknown fields are excluded. Preview is local to this request and never submits a lead.</p>';if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Mapping saved.</p></div>';
 if($preview!==null){echo '<h2>Preview — no lead sent or saved</h2>';if(isset($preview['error']))echo '<div class="notice notice-error"><p>'.esc_html($preview['error']).'</p></div>';else{if(!empty($preview['ambiguities']))echo '<div class="notice notice-warning"><p>Multiple possible source fields detected. Select the intended path for each ambiguous field and explicitly confirm before saving.</p></div>';echo '<pre style="white-space:pre-wrap;background:#fff;border:1px solid #ddd;padding:14px;max-height:420px;overflow:auto">'.esc_html(wp_json_encode($preview,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>';}}
 echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="kcb_save_mapping">';wp_nonce_field('kcb_save_mapping');self::fields($c);submit_button('Save confirmed mapping');echo '</form><hr><h2>Sample JSON preview</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="kcb_preview_mapping">';wp_nonce_field('kcb_preview_mapping');self::fields($c);echo '<p><label for="kcb-sample">Sample JSON (up to 256 KB; never retained)</label></p><textarea id="kcb-sample" name="sample_json" rows="10" class="large-text code" maxlength="262144" required></textarea>';submit_button('Preview mapping (no API request)','secondary');echo '</form></div>';}
 static function fields($c){echo '<table class="form-table"><tbody>';foreach(KCB_Field_Mapper::FIELDS as $field){$v=$c['fields'][$field]??'';echo '<tr><th><label for="map-'.esc_attr($field).'">'.esc_html($field).'</label></th><td><input id="map-'.esc_attr($field).'" class="regular-text code" name="mapping[fields]['.esc_attr($field).']" value="'.esc_attr($v).'" placeholder="customer.full_name"><p class="description">Aliases: '.esc_html(implode(', ',KCB_Field_Mapper::ALIASES[$field])).'</p></td></tr>';}
 echo '<tr><th>Array path</th><td><input class="regular-text code" name="mapping[array_path]" value="'.esc_attr($c['array_path']).'" placeholder="Empty = one lead, $ = root array, or data.leads"><p class="description">Arrays must be explicitly selected; maximum 100 leads.</p></td></tr><tr><th>Affirmative consent values</th><td><input class="regular-text" name="mapping[yes]" value="'.esc_attr(implode(',',$c['yes'])).'"><p class="description">Comma-separated exact values; missing or other values always become false.</p></td></tr><tr><th>Confirm mapping</th><td><label><input type="checkbox" name="mapping[confirmed]" value="1" '.checked(!empty($c['confirmed']),true,false).'> I reviewed the mapping, including any ambiguous aliases, and approve its use.</label></td></tr></tbody></table>';}
}
KCB_Mapping_Admin::init();
